def histogram(test):
    from collections import Counter
    letters = test.split()
    if not letters:
        return {}
    counter = Counter(letters)
    max_count = max(counter.values())
    return {k: v for k, v in counter.items() if v == max_count}

def maximum(arr, k):
    if k == 0:
        return []
    sorted_arr = sorted(arr, reverse=True)
    top_k = sorted_arr[:k]
    return sorted(top_k)

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0:
            total += num ** 3
        else:
            total += num
    return total

def compare_one(a, b):
    def to_num(x):
        if isinstance(x, str):
            x = x.replace(',', '.')
        return float(x)
    num_a = to_num(a)
    num_b = to_num(b)
    if num_a == num_b:
        return None
    return a if num_a > num_b else b

